// dropbox-save-round-files/index.ts
//
// Called by a Supabase DB trigger on INSERT to scene_rounds.
// Creates Round-{nn}/ inside the scene's AS_Assets subfolder, then:
//   1. Copies all round_uploads files for this scene from Supabase Storage → Dropbox
//   2. If scene_rounds.instructions is set, generates a PDF and uploads it
//   3. If asset_drawings exist for this round, serialises them as JSON and uploads
//
// Note: round_uploads has scene_id but no round_number column, so all uploads
// for the scene are copied. This mirrors the data model where uploads are
// submitted as part of creating the round and belong to the latest submission.
//
// Deploy: npx supabase functions deploy dropbox-save-round-files \
//           --project-ref oodhsoiwnqxcimzmzick --no-verify-jwt

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { PDFDocument, StandardFonts, rgb, PDFName, PDFString, PDFArray } from "npm:pdf-lib@1.17.1";
import { requireInternalOrAdmin } from "../_shared/cronAuth.ts";

const PROJECTS_ROOT = "/00_Production/PRD01_Client-Projects";

// ── Dropbox helpers ───────────────────────────────────────────────────────────

async function refreshToken(
  connection: Record<string, string>,
  supabase: ReturnType<typeof createClient>,
): Promise<string | null> {
  const appKey = Deno.env.get("DROPBOX_APP_KEY")!;
  const appSecret = Deno.env.get("DROPBOX_APP_SECRET")!;
  try {
    const res = await fetch("https://api.dropboxapi.com/oauth2/token", {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        Authorization: `Basic ${btoa(`${appKey}:${appSecret}`)}`,
      },
      body: new URLSearchParams({
        grant_type: "refresh_token",
        refresh_token: connection.refresh_token,
      }),
    });
    if (!res.ok) return null;
    const data = await res.json();
    const expiresAt = data.expires_in
      ? new Date(Date.now() + data.expires_in * 1000).toISOString()
      : null;
    await supabase
      .from("dropbox_connections")
      .update({ access_token: data.access_token, token_expires_at: expiresAt })
      .eq("id", connection.id);
    return data.access_token;
  } catch {
    return null;
  }
}

function dropboxHeaders(
  accessToken: string,
  namespaceId: string | null,
): Record<string, string> {
  const h: Record<string, string> = {
    Authorization: `Bearer ${accessToken}`,
    "Content-Type": "application/json",
  };
  if (namespaceId) {
    h["Dropbox-API-Path-Root"] = JSON.stringify({
      ".tag": "namespace_id",
      namespace_id: namespaceId,
    });
  }
  return h;
}

async function getRootNamespaceId(accessToken: string): Promise<string | null> {
  const res = await fetch(
    "https://api.dropboxapi.com/2/users/get_current_account",
    { method: "POST", headers: { Authorization: `Bearer ${accessToken}` } },
  );
  if (!res.ok) return null;
  const data = await res.json();
  return data?.root_info?.root_namespace_id ?? null;
}

async function createFolder(
  accessToken: string,
  path: string,
  namespaceId: string | null,
): Promise<void> {
  const res = await fetch(
    "https://api.dropboxapi.com/2/files/create_folder_v2",
    {
      method: "POST",
      headers: dropboxHeaders(accessToken, namespaceId),
      body: JSON.stringify({ path, autorename: false }),
    },
  );
  if (res.ok) return;
  const errText = await res.text();
  if (errText.includes("path/conflict")) {
    console.log(`[dropbox-save-round-files] Folder already exists: ${path}`);
    return;
  }
  throw new Error(`create_folder_v2 failed for ${path}: ${errText}`);
}

async function uploadToDropbox(
  accessToken: string,
  dropboxPath: string,
  content: Uint8Array,
  namespaceId: string | null,
): Promise<void> {
  const apiArg = JSON.stringify({
    path: dropboxPath,
    mode: "overwrite",
    autorename: false,
    mute: true,
  });

  const headers: Record<string, string> = {
    Authorization: `Bearer ${accessToken}`,
    "Content-Type": "application/octet-stream",
    "Dropbox-API-Arg": apiArg,
  };
  if (namespaceId) {
    headers["Dropbox-API-Path-Root"] = JSON.stringify({
      ".tag": "namespace_id",
      namespace_id: namespaceId,
    });
  }

  const res = await fetch("https://content.dropboxapi.com/2/files/upload", {
    method: "POST",
    headers,
    body: content,
  });
  if (!res.ok) {
    const err = await res.text();
    throw new Error(`Dropbox upload failed for ${dropboxPath}: ${err}`);
  }
}

// Find a folder inside parentPath whose name starts with {prefix}_ (case-insensitive).
async function findFolderByPrefix(
  accessToken: string,
  parentPath: string,
  prefix: string,
  namespaceId: string | null,
): Promise<string | null> {
  const res = await fetch("https://api.dropboxapi.com/2/files/list_folder", {
    method: "POST",
    headers: dropboxHeaders(accessToken, namespaceId),
    body: JSON.stringify({ path: parentPath, recursive: false }),
  });
  if (!res.ok) return null;
  const data = await res.json();
  const p = prefix.toLowerCase() + "_";
  const match = (data.entries ?? []).find(
    (e: Record<string, unknown>) =>
      e[".tag"] === "folder" &&
      (e.name as string).toLowerCase().startsWith(p),
  );
  return match ? (match.path_display as string) : null;
}

// Create (or retrieve existing) a public shared link for a Dropbox file.
// Returns the URL, or null on failure.
async function createDropboxSharedLink(
  accessToken: string,
  dropboxPath: string,
  namespaceId: string | null,
): Promise<string | null> {
  try {
    const res = await fetch(
      "https://api.dropboxapi.com/2/sharing/create_shared_link_settings_v2",
      {
        method: "POST",
        headers: dropboxHeaders(accessToken, namespaceId),
        body: JSON.stringify({
          path: dropboxPath,
          settings: { requested_visibility: "public" },
        }),
      },
    );

    if (res.ok) {
      const data = await res.json();
      return (data.url as string) ?? null;
    }

    if (res.status === 409) {
      // A shared link already exists — extract its URL from the error body
      const errData = await res.json();
      const url = errData?.error?.shared_link_already_exists?.metadata?.url as string | undefined;
      if (url) return url;
    }

    console.warn(`[dropbox-save-round-files] Shared link failed for ${dropboxPath}: ${res.status}`);
    return null;
  } catch (e) {
    console.warn(`[dropbox-save-round-files] Shared link exception for ${dropboxPath}:`, e);
    return null;
  }
}

// ── PDF generation ────────────────────────────────────────────────────────────

// Full-logo base64 PNG (600×91 greyscale, from src/lib/brandLogo.ts)
const LOGO_BASE64 = "";

type UploadInfo = { category: string; file_name: string; shared_url?: string | null };

const CATEGORY_DISPLAY: Record<string, string> = {
  floor_plan: "Floor Plan",
  elevations: "Elevations",
  rcp: "Reflected Ceiling Plan",
  finishes_schedule: "Finishes Schedule",
  furniture_schedule: "Furniture Schedule",
  lighting_plan: "Lighting Plan",
  lighting_mood_reference: "Lighting Mood Reference",
  models_3d: "3D Models",
  cgi_package: "CGI Package",
};

function formatTimestamp(iso: string): string {
  const d = new Date(iso);
  const date = new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "long", year: "numeric" }).format(d);
  const time = new Intl.DateTimeFormat("en-GB", { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false }).format(d);
  return `${date} at ${time}`;
}

function wrapTextPx(
  text: string,
  pdfFont: { widthOfTextAtSize: (t: string, s: number) => number },
  size: number,
  maxWidth: number,
): string[] {
  const result: string[] = [];
  for (const paragraph of text.split("\n")) {
    if (!paragraph.trim()) { result.push(""); continue; }
    const words = paragraph.split(/\s+/);
    let line = "";
    for (const word of words) {
      const test = line ? `${line} ${word}` : word;
      if (pdfFont.widthOfTextAtSize(test, size) <= maxWidth) { line = test; } else {
        if (line) result.push(line);
        line = word;
      }
    }
    if (line) result.push(line);
  }
  return result;
}

function classifyLine(line: string): "heading" | "definition" | "body" | "empty" {
  const t = line.trim();
  if (!t) return "empty";
  if (t === t.toUpperCase() && /[A-Z]/.test(t) && t.length < 80) return "heading";
  const ci = t.indexOf(":");
  if (ci > 0 && ci < 25) return "definition";
  return "body";
}

async function buildInstructionsPdf(
  projectName: string,
  sceneName: string,
  projectCode: string,
  sceneCode: string,
  roundNumber: number,
  roundCreatedAt: string,
  instructions: string,
  uploads: UploadInfo[],
): Promise<Uint8Array> {
  const doc = await PDFDocument.create();
  const regFont = await doc.embedFont(StandardFonts.Helvetica);
  const boldFont = await doc.embedFont(StandardFonts.HelveticaBold);
  const titleFont = await doc.embedFont(StandardFonts.TimesRoman);

  const A4_W = 595.28;
  const A4_H = 841.89;
  const ML = 72;
  const MR = 72;
  const CW = A4_W - ML - MR;

  const BG = rgb(0.929, 0.910, 0.878);
  const RULE_C = rgb(0.541, 0.502, 0.439);
  const WARM_BLACK = rgb(0.102, 0.094, 0.078);

  // Attach a URI hyperlink annotation to a rect on the current page
  function addLink(
    pg: ReturnType<typeof doc.addPage>,
    x: number,
    y: number,
    width: number,
    size: number,
    url: string,
  ): void {
    const annot = doc.context.obj({
      Type: "Annot",
      Subtype: "Link",
      Rect: doc.context.obj([x, y - 2, x + width, y + size]),
      Border: doc.context.obj([0, 0, 0]),
      A: doc.context.obj({
        Type: "Action",
        S: "URI",
        URI: PDFString.of(url),
      }),
    });
    const ref = doc.context.register(annot);
    const existing = pg.node.get(PDFName.of("Annots"));
    if (existing instanceof PDFArray) {
      existing.push(ref);
    } else {
      pg.node.set(PDFName.of("Annots"), doc.context.obj([ref]));
    }
  }

  const logoBinary = atob(LOGO_BASE64);
  const logoBytes = new Uint8Array(logoBinary.length);
  for (let i = 0; i < logoBinary.length; i++) logoBytes[i] = logoBinary.charCodeAt(i);
  const logoImage = await doc.embedPng(logoBytes);
  const LOGO_W = 180;
  const LOGO_H = Math.round((91 / 600) * LOGO_W);

  const FOOTER_RULE_Y = 55;
  const FOOTER_SIZE = 6.5;
  const FOOTER_LH = 9;
  const FOOTER_TEXT = "CONFIDENTIAL: This document contains proprietary information intended for the named recipient only. · Unauthorised use, disclosure, or distribution is strictly prohibited. If received in error, please notify the sender and destroy all copies.";
  const CONTENT_BOTTOM_Y = FOOTER_RULE_Y + 24;

  function newPage(): [ReturnType<typeof doc.addPage>, number] {
    const pg = doc.addPage([A4_W, A4_H]);
    pg.drawRectangle({ x: 0, y: 0, width: A4_W, height: A4_H, color: BG });
    pg.drawLine({ start: { x: ML, y: FOOTER_RULE_Y }, end: { x: A4_W - MR, y: FOOTER_RULE_Y }, thickness: 0.5, color: RULE_C });
    const fLines = wrapTextPx(FOOTER_TEXT, regFont, FOOTER_SIZE, CW);
    for (let i = 0; i < fLines.length; i++) {
      const lw = regFont.widthOfTextAtSize(fLines[i], FOOTER_SIZE);
      pg.drawText(fLines[i], { x: (A4_W - lw) / 2, y: FOOTER_RULE_Y - 12 - i * FOOTER_LH, size: FOOTER_SIZE, font: regFont, color: RULE_C });
    }
    return [pg, A4_H - 64];
  }

  let [page, y] = newPage();

  // ── Logo ─────────────────────────────────────────────────────────────────────
  page.drawImage(logoImage, { x: (A4_W - LOGO_W) / 2, y: y - LOGO_H, width: LOGO_W, height: LOGO_H });
  y -= LOGO_H + 32;

  // ── Title block ──────────────────────────────────────────────────────────────
  const TITLE_SIZE = 18;
  const TITLE_PAD = 18;
  const titleText = `${projectName} — ${sceneName}`;
  const titleLines = wrapTextPx(titleText, titleFont, TITLE_SIZE, CW);
  const titleBlockH = 2 * TITLE_PAD + titleLines.length * (TITLE_SIZE + 4) - 4;

  const rule1Y = y;
  const rule2Y = rule1Y - titleBlockH;
  page.drawLine({ start: { x: ML, y: rule1Y }, end: { x: A4_W - MR, y: rule1Y }, thickness: 0.5, color: RULE_C });

  // Centre title: midY between rules, baseline = midY + totalTitleH/2 - TITLE_SIZE (top of first line at midY + totalH/2)
  const midY = (rule1Y + rule2Y) / 2;
  const totalTitleH = titleLines.length * TITLE_SIZE + (titleLines.length - 1) * 4;
  const firstBaselineY = midY + totalTitleH / 2 - TITLE_SIZE;
  for (let i = 0; i < titleLines.length; i++) {
    const tw = titleFont.widthOfTextAtSize(titleLines[i], TITLE_SIZE);
    page.drawText(titleLines[i], { x: (A4_W - tw) / 2, y: firstBaselineY - i * (TITLE_SIZE + 4), size: TITLE_SIZE, font: titleFont, color: WARM_BLACK });
  }

  page.drawLine({ start: { x: ML, y: rule2Y }, end: { x: A4_W - MR, y: rule2Y }, thickness: 0.5, color: RULE_C });
  y = rule2Y - 20;

  // ── Metadata ─────────────────────────────────────────────────────────────────
  const META_SIZE = 7;
  const META_LH = 12;
  const roundPad = String(roundNumber).padStart(2, "0");
  const ts = formatTimestamp(roundCreatedAt);

  // ROUND — label then large serif value
  page.drawText("ROUND", { x: ML, y, size: 7.5, font: regFont, color: RULE_C });
  y -= 8;
  const roundValW = titleFont.widthOfTextAtSize(roundPad, 28);
  page.drawText(roundPad, { x: ML, y: y - 28, size: 28, font: titleFont, color: WARM_BLACK });
  y -= 28 + 16;

  // SUBMITTED
  const subLabel = "SUBMITTED";
  const subLW = regFont.widthOfTextAtSize(subLabel, META_SIZE);
  page.drawText(subLabel, { x: ML, y, size: META_SIZE, font: regFont, color: RULE_C });
  page.drawText(ts, { x: ML + subLW + 6, y, size: META_SIZE, font: regFont, color: WARM_BLACK });
  y -= META_LH + 16;

  // ── Instructions header ───────────────────────────────────────────────────────
  if (y < CONTENT_BOTTOM_Y) [page, y] = newPage();
  page.drawText("INSTRUCTIONS", { x: ML, y, size: 7.5, font: regFont, color: RULE_C });
  y -= 7.5 + 6;

  // ── Body text ─────────────────────────────────────────────────────────────────
  const BODY_SIZE = 10;
  const BODY_LH = Math.round(BODY_SIZE * 1.65);
  const SECTION_SIZE = 7.5;
  const DEF_TERM_SIZE = 9;

  let prevType: string | null = null;
  for (const raw of instructions.split("\n")) {
    const type = classifyLine(raw);

    if (type === "empty") {
      y -= 10;
      prevType = "empty";
      continue;
    }

    if (y < CONTENT_BOTTOM_Y) [page, y] = newPage();

    if (type === "heading") {
      if (prevType !== null && prevType !== "empty") y -= 10;
      if (y < CONTENT_BOTTOM_Y) [page, y] = newPage();
      page.drawText(raw.trim().toUpperCase(), { x: ML, y, size: SECTION_SIZE, font: regFont, color: RULE_C });
      y -= SECTION_SIZE + 6;
      prevType = "heading";
      continue;
    }

    if (type === "definition") {
      const t = raw.trim();
      const ci = t.indexOf(":");
      const term = t.substring(0, ci + 1);
      const rest = t.substring(ci + 1).trimStart();
      const termW = boldFont.widthOfTextAtSize(term, DEF_TERM_SIZE);
      const restLines = wrapTextPx(rest, regFont, BODY_SIZE, CW - termW - 5);
      page.drawText(term, { x: ML, y, size: DEF_TERM_SIZE, font: boldFont, color: WARM_BLACK });
      if (restLines.length > 0) {
        page.drawText(restLines[0], { x: ML + termW + 5, y, size: BODY_SIZE, font: regFont, color: WARM_BLACK });
      }
      y -= BODY_LH;
      for (let j = 1; j < restLines.length; j++) {
        if (y < CONTENT_BOTTOM_Y) [page, y] = newPage();
        page.drawText(restLines[j], { x: ML, y, size: BODY_SIZE, font: regFont, color: WARM_BLACK });
        y -= BODY_LH;
      }
      prevType = "definition";
      continue;
    }

    // body paragraph
    for (const bl of wrapTextPx(raw.trim(), regFont, BODY_SIZE, CW)) {
      if (y < CONTENT_BOTTOM_Y) [page, y] = newPage();
      page.drawText(bl, { x: ML, y, size: BODY_SIZE, font: regFont, color: WARM_BLACK });
      y -= BODY_LH;
    }
    prevType = "body";
  }

  // ── Attachments list ──────────────────────────────────────────────────────────
  if (uploads.length > 0) {
    if (prevType !== null) y -= 16;
    if (y < CONTENT_BOTTOM_Y) [page, y] = newPage();

    // Section header
    page.drawText("ATTACHMENTS", { x: ML, y, size: 7.5, font: regFont, color: RULE_C });
    y -= 7.5 + 6;

    const NUM_W = 24;    // width of "01  " prefix column
    const CAT_W = 120;   // fixed-width category column
    const FILE_SIZE = 8;
    const FILE_LH = 8 + 8; // 8pt text + 8pt gap between items

    for (let idx = 0; idx < uploads.length; idx++) {
      if (y < CONTENT_BOTTOM_Y) [page, y] = newPage();
      const num = String(idx + 1).padStart(2, "0");
      const cat = CATEGORY_DISPLAY[uploads[idx].category] ?? uploads[idx].category.replace(/_/g, " ");

      // "01" in warm grey
      page.drawText(num, { x: ML, y, size: FILE_SIZE, font: regFont, color: RULE_C });
      // category in bold
      page.drawText(cat, { x: ML + NUM_W, y, size: FILE_SIZE, font: boldFont, color: WARM_BLACK });
      // filename in serif regular — hyperlinked if a shared URL is available
      const fnX = ML + NUM_W + CAT_W;
      page.drawText(uploads[idx].file_name, { x: fnX, y, size: FILE_SIZE, font: titleFont, color: WARM_BLACK });
      if (uploads[idx].shared_url) {
        const fnW = titleFont.widthOfTextAtSize(uploads[idx].file_name, FILE_SIZE);
        addLink(page, fnX, y, fnW, FILE_SIZE, uploads[idx].shared_url!);
      }
      y -= FILE_LH;
    }
  }

  return doc.save();
}

// ── Main handler ──────────────────────────────────────────────────────────────

async function delay(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: { "Access-Control-Allow-Origin": "*" } });
  }

  const auth = await requireInternalOrAdmin(req);
  if (!auth.ok) return auth.response;

  const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const supabase = createClient(supabaseUrl, serviceKey);

  try {
    const body = await req.json() as { record: Record<string, unknown> };
    const record = body.record;
    const roundId = record.id as string;
    const sceneId = record.scene_id as string;
    const roundNumber = record.round_number as number;
    const instructions = record.instructions as string | null;

    if (!roundId || !sceneId || roundNumber == null) {
      return new Response(JSON.stringify({ error: "Missing required fields" }), { status: 400 });
    }

    // Draft gate: drafts must never touch Dropbox. The folder + file
    // upload + instructions PDF only happen when the client submits the
    // draft for production (status transitions away from 'draft'). The
    // sync at submit time fires from a separate code path (see Submit
    // For Production handler in NewRoundModal).
    if (record.status === "draft") {
      console.log(`[dropbox-save-round-files] skipping for draft round ${roundId}`);
      return new Response(JSON.stringify({ skipped: true, reason: "draft" }), {
        headers: { "Access-Control-Allow-Origin": "*", "Content-Type": "application/json" },
      });
    }

    console.log(`[dropbox-save-round-files] round=${roundId} scene=${sceneId} number=${roundNumber}`);

    // Get Dropbox connection
    const { data: connection } = await supabase
      .from("dropbox_connections")
      .select("id, access_token, refresh_token, token_expires_at")
      .limit(1)
      .maybeSingle();

    if (!connection) {
      console.warn("[dropbox-save-round-files] Dropbox not connected — skipping");
      return new Response(JSON.stringify({ skipped: true, reason: "dropbox_not_connected" }));
    }

    let accessToken = connection.access_token as string;
    if (
      connection.token_expires_at &&
      new Date(connection.token_expires_at as string) < new Date()
    ) {
      accessToken = (await refreshToken(connection as Record<string, string>, supabase)) ?? accessToken;
    }

    const namespaceId = await getRootNamespaceId(accessToken);

    // Resolve scene folder — poll up to 5×2s for scene trigger to finish
    let sceneFolder: string | null = null;
    let sceneName = "";
    let sceneCode = "";
    let projectCode = "";
    let projectName = "";

    for (let attempt = 0; attempt < 5; attempt++) {
      const { data: scene } = await supabase
        .from("scenes")
        .select("dropbox_folder, scene_code, project_id, name, projects(name, project_code, dropbox_folder)")
        .eq("id", sceneId)
        .single();

      sceneName = (scene?.name as string) ?? "";
      sceneCode = (scene?.scene_code as string) ?? "";
      const proj = scene?.projects as Record<string, unknown> | null;
      projectCode = (proj?.project_code as string) ?? "";
      projectName = (proj?.name as string) ?? "";

      if (scene?.dropbox_folder) {
        sceneFolder = scene.dropbox_folder as string;
        break;
      }

      // Fallback: resolve via project + scene codes via prefix search
      if (proj?.dropbox_folder && scene?.scene_code) {
        sceneFolder = await findFolderByPrefix(
          accessToken,
          proj.dropbox_folder as string,
          scene.scene_code as string,
          namespaceId,
        );
        if (sceneFolder) break;
      }

      if (attempt < 4) {
        console.log(`[dropbox-save-round-files] scene.dropbox_folder not set yet, waiting… (attempt ${attempt + 1})`);
        await delay(2000);
      }
    }

    if (!sceneFolder) {
      throw new Error(
        `Cannot resolve Dropbox folder for scene ${sceneId}. ` +
        "Ensure dropbox-create-scene-folder has run successfully first.",
      );
    }

    const roundPad = String(roundNumber).padStart(2, "0");
    const roundFolderPath = `${sceneFolder}/INS_Instructions/Round-${roundPad}`;

    console.log(`[dropbox-save-round-files] Creating round folder: ${roundFolderPath}`);
    await createFolder(accessToken, roundFolderPath, namespaceId);

    const CATEGORY_FOLDERS: Record<string, string> = {
      floor_plan:               "Floor-Plan",
      elevations:               "Elevations",
      rcp:                      "Reflected-Ceiling-Plan",
      finishes_schedule:        "Finishes-Schedule",
      furniture_schedule:       "Furniture-Schedule",
      lighting_plan:            "Lighting-Plan",
      lighting_mood_reference:  "Lighting-Mood-Reference",
      models_3d:                "3D-Models",
      cgi_package:              "CGI-Package",
    };

    let filesCopied = 0;
    let filesErrored = 0;

    // ── 1. Copy round_uploads files ───────────────────────────────────────────
    const { data: uploads } = await supabase
      .from("round_uploads")
      .select("id, file_name, storage_path, category")
      .eq("scene_id", sceneId)
      .order("created_at", { ascending: true });

    // Map filename → shared Dropbox URL, populated during upload
    const sharedUrls = new Map<string, string>();

    // Pre-create one subfolder per category that has at least one file
    const categoriesPresent = new Set(
      (uploads ?? []).map((u) => u.category as string).filter(Boolean),
    );
    const createdFolders = new Set<string>();
    for (const cat of categoriesPresent) {
      const folderName = CATEGORY_FOLDERS[cat];
      if (!folderName) continue;
      const folderPath = `${roundFolderPath}/${folderName}`;
      await createFolder(accessToken, folderPath, namespaceId);
      createdFolders.add(cat);
    }

    for (const upload of uploads ?? []) {
      try {
        const { data: fileData, error: dlErr } = await supabase.storage
          .from("round-uploads")
          .download(upload.storage_path as string);

        if (dlErr || !fileData) {
          console.warn(
            `[dropbox-save-round-files] Failed to download ${upload.storage_path}: ${dlErr?.message}`,
          );
          filesErrored++;
          continue;
        }

        const bytes = new Uint8Array(await fileData.arrayBuffer());
        const cat = upload.category as string;
        const folderName = CATEGORY_FOLDERS[cat];
        const targetFolder = folderName ? `${roundFolderPath}/${folderName}` : roundFolderPath;
        const dropboxPath = `${targetFolder}/${upload.file_name}`;
        await uploadToDropbox(accessToken, dropboxPath, bytes, namespaceId);
        filesCopied++;
        console.log(`[dropbox-save-round-files] Uploaded: ${upload.file_name} → ${targetFolder}`);

        // Generate a public shared link and store it
        const sharedUrl = await createDropboxSharedLink(accessToken, dropboxPath, namespaceId);
        if (sharedUrl) {
          sharedUrls.set(upload.file_name as string, sharedUrl);
          // Persist to round_uploads (best-effort — requires migration 20260512000004)
          const uploadId = (upload as any).id as string | undefined;
          if (uploadId) {
            supabase.from("round_uploads").update({ dropbox_shared_url: sharedUrl }).eq("id", uploadId).then(() => {});
          }
        }
      } catch (e) {
        console.error(
          `[dropbox-save-round-files] Error uploading ${upload.file_name}:`,
          e instanceof Error ? e.message : e,
        );
        filesErrored++;
      }
    }

    // ── 2. Generate instructions PDF ──────────────────────────────────────────
    // Enrich upload list with shared URLs for clickable PDF links
    const uploadsForPdf: UploadInfo[] = (uploads ?? []).map((u) => ({
      category: u.category as string,
      file_name: u.file_name as string,
      shared_url: sharedUrls.get(u.file_name as string) ?? null,
    }));

    if (instructions) {
      try {
        const roundCreatedAt = (record.created_at as string) ?? new Date().toISOString();
        const pdfBytes = await buildInstructionsPdf(
          projectName, sceneName, projectCode, sceneCode,
          roundNumber, roundCreatedAt, instructions, uploadsForPdf,
        );
        const pdfName = `${projectCode}-${sceneCode}_Round-${roundPad}_Instructions.pdf`;
        const pdfPath = `${roundFolderPath}/${pdfName}`;
        await uploadToDropbox(accessToken, pdfPath, pdfBytes, namespaceId);
        console.log(`[dropbox-save-round-files] Instructions PDF uploaded: ${pdfPath}`);
      } catch (e) {
        console.error(
          "[dropbox-save-round-files] Failed to generate/upload instructions PDF:",
          e instanceof Error ? e.message : e,
        );
      }
    }

    // ── 3. Serialise asset_drawings as JSON ───────────────────────────────────
    const { data: drawings } = await supabase
      .from("asset_drawings")
      .select("id, asset_id, created_by, points, color, created_at")
      .eq("scene_round_id", roundId);

    if (drawings && drawings.length > 0) {
      try {
        const jsonBytes = new TextEncoder().encode(
          JSON.stringify({ round_id: roundId, strokes: drawings }, null, 2),
        );
        const jsonPath = `${roundFolderPath}/Round-${roundPad}_Annotations.json`;
        await uploadToDropbox(accessToken, jsonPath, jsonBytes, namespaceId);
        console.log(
          `[dropbox-save-round-files] Annotations JSON uploaded: ${drawings.length} strokes`,
        );
      } catch (e) {
        console.error(
          "[dropbox-save-round-files] Failed to upload annotations JSON:",
          e instanceof Error ? e.message : e,
        );
      }
    }

    console.log(
      `[dropbox-save-round-files] Done. files=${filesCopied} errors=${filesErrored} ` +
      `instructions=${!!instructions} drawings=${drawings?.length ?? 0}`,
    );

    return new Response(
      JSON.stringify({
        success: true,
        roundFolderPath,
        filesCopied,
        filesErrored,
        instructionsPdf: !!instructions,
        annotationsJson: (drawings?.length ?? 0) > 0,
      }),
      { headers: { "Content-Type": "application/json" } },
    );
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error("[dropbox-save-round-files] Error:", msg);
    return new Response(JSON.stringify({ error: msg }), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });
  }
});
